// === RECOPILAR DATOS ===
const inventory = $('Inventario').first().json.results || $('Inventario').first().json.data || [];
const sales = $('Ventas').first().json.results || $('Ventas').first().json.data || [];
const orders = $('Pedidos').first().json.results || $('Pedidos').first().json.data || [];
const support = $('Soporte').first().json.results || $('Soporte').first().json.data || [];

// === PARSEAR INVENTARIO ===
const inventoryParsed = inventory.map(book => {
  const p = book.properties || {};
  return {
    title: p.Nombre?.title?.[0]?.plain_text || '',
    author: p.Autor?.rich_text?.[0]?.plain_text || '',
    genre: p.Genero?.select?.name || 'Otros',
    estadoPublicacion: p['Estado publicacion']?.select?.name || '',
    estadoFisico: p['Estado fisico']?.select?.name || '',
    coste: p.Coste?.number || 0,
    precioVenta: p['Precio venta']?.number || 0,
    fechaEntrada: p['date:Fecha entrada:start'] || '',
    marketingGenerado: p['Marketing generado'] === '__YES__',
    sku: p.SKU?.number || p.SKU?.formula_string || '',
    isbn: p.ISBN?.rich_text?.[0]?.plain_text || ''
  };
});

// === PARSEAR VENTAS ===
const salesParsed = sales.map(sale => {
  const p = sale.properties || {};
  return {
    titulo: p.Titulo?.title?.[0]?.plain_text || '',
    orderId: p['Nº Pedido']?.rich_text?.[0]?.plain_text || '',
    sku: p.SKU?.rich_text?.[0]?.plain_text || '',
    autor: p.Autor?.rich_text?.[0]?.plain_text || '',
    genero: p.Genero?.select?.name || 'Otros',
    plataforma: p.Plataforma?.select?.name || 'Otros',
    precioVenta: p['Precio venta']?.number || 0,
    coste: p.Coste?.number || 0,
    margenEur: p['Margen eur']?.number || 0,
    margenPct: p['Margen %']?.number || 0,
    diasStock: p['Dias en stock']?.number || 0,
    estadoPedido: p['Estado pedido']?.select?.name || '',
    fechaVenta: p['date:Fecha venta:start'] || ''
  };
});

// === PARSEAR PEDIDOS ===
const ordersParsed = orders.map(order => {
  const p = order.properties || {};
  return {
    orderId: p['Nº Pedido']?.title?.[0]?.plain_text || '',
    cliente: p.Cliente?.rich_text?.[0]?.plain_text || '',
    email: p.Email?.rich_text?.[0]?.plain_text || '',
    estadoPedido: p['Estado pedido']?.select?.name || '',
    importeTotal: p['Importe total']?.number || 0,
    plataforma: p.Plataforma?.select?.name || 'Otros',
    fecha: p['date:Fecha:start'] || ''
  };
});

// === PARSEAR SOPORTE ===
const supportParsed = support.map(ticket => {
  const p = ticket.properties || {};
  return {
    asunto: p.Asunto?.title?.[0]?.plain_text || '',
    cliente: p.Cliente?.rich_text?.[0]?.plain_text || '',
    canal: p.Canal?.select?.name || '',
    tema: p.Tema?.select?.name || 'Otro',
    prioridad: p.Prioridad?.select?.name || 'Media',
    estadoTicket: p['Estado ticket']?.select?.name || '',
    fecha: p['date:Fecha:start'] || ''
  };
});

// === CALCULAR FECHAS ===
const now = new Date();
const oneWeekAgo = new Date(now.getTime() - 7 * 86400000);
const oneMonthAgo = new Date(now.getTime() - 30 * 86400000);
const formatDate = d => d.toISOString().split('T')[0];

// Filtrar ventas de esta semana
const salesThisWeek = salesParsed.filter(s => {
  if (!s.fechaVenta) return false;
  const d = new Date(s.fechaVenta);
  return d >= oneWeekAgo && d <= now;
});

const salesThisMonth = salesParsed.filter(s => {
  if (!s.fechaVenta) return false;
  const d = new Date(s.fechaVenta);
  return d >= oneMonthAgo && d <= now;
});

// === METRICAS DE VENTAS ===
const totalVentasSemana = salesThisWeek.reduce((sum, s) => sum + s.precioVenta, 0);
const totalVentasMes = salesThisMonth.reduce((sum, s) => sum + s.precioVenta, 0);
const numPedidosSemana = ordersParsed.filter(o => o.fecha && new Date(o.fecha) >= oneWeekAgo).length;
const numLibrosVendidosSemana = salesThisWeek.length;
const ticketMedio = numPedidosSemana > 0 ? totalVentasSemana / numPedidosSemana : 0;

// Ventas por plataforma
const ventasPorPlataforma = {};
salesThisWeek.forEach(s => {
  ventasPorPlataforma[s.plataforma] = (ventasPorPlataforma[s.plataforma] || 0) + s.precioVenta;
});

// Top generos vendidos
const generosVendidos = {};
salesParsed.forEach(s => {
  generosVendidos[s.genero] = (generosVendidos[s.genero] || 0) + 1;
});
const topGeneros = Object.entries(generosVendidos).sort((a, b) => b[1] - a[1]).slice(0, 5);

// Top autores vendidos
const autoresVendidos = {};
salesParsed.forEach(s => {
  autoresVendidos[s.autor] = (autoresVendidos[s.autor] || 0) + 1;
});
const topAutores = Object.entries(autoresVendidos).sort((a, b) => b[1] - a[1]).slice(0, 5);

// === METRICAS DE RENTABILIDAD ===
const costeTotalVendido = salesParsed.reduce((sum, s) => sum + s.coste, 0);
const margenBrutoEur = salesParsed.reduce((sum, s) => sum + s.margenEur, 0);
const margenBrutoPct = totalVentasMes > 0 ? (margenBrutoEur / salesParsed.reduce((s, x) => s + x.precioVenta, 0)) * 100 : 0;

// Margen por genero
const margenPorGenero = {};
salesParsed.forEach(s => {
  if (!margenPorGenero[s.genero]) margenPorGenero[s.genero] = { margen: 0, ventas: 0 };
  margenPorGenero[s.genero].margen += s.margenEur;
  margenPorGenero[s.genero].ventas += s.precioVenta;
});

// === METRICAS DE INVENTARIO ===
const stockDisponible = inventoryParsed.filter(b => b.estadoPublicacion === 'Publicado');
const stockReservado = inventoryParsed.filter(b => b.estadoPublicacion === 'Reservado');
const stockVendido = inventoryParsed.filter(b => b.estadoPublicacion === 'Vendido');
const stockRetirado = inventoryParsed.filter(b => b.estadoPublicacion === 'Retirado');

const valorInventario = stockDisponible.reduce((sum, b) => sum + b.precioVenta, 0);
const costeInventario = stockDisponible.reduce((sum, b) => sum + b.coste, 0);

// Libros sin vender +30/+60/+90 dias
const librosSinVender30 = inventoryParsed.filter(b => {
  if (!b.fechaEntrada) return false;
  const dias = (now - new Date(b.fechaEntrada)) / 86400000;
  return b.estadoPublicacion === 'Publicado' && dias > 30;
});
const librosSinVender60 = librosSinVender30.filter(b => {
  const dias = (now - new Date(b.fechaEntrada)) / 86400000;
  return dias > 60;
});
const librosSinVender90 = librosSinVender60.filter(b => {
  const dias = (now - new Date(b.fechaEntrada)) / 86400000;
  return dias > 90;
});

// Stock por genero
const stockPorGenero = {};
stockDisponible.forEach(b => {
  stockPorGenero[b.genre] = (stockPorGenero[b.genre] || 0) + 1;
});

// Libros publicados sin marketing
const sinMarketing = inventoryParsed.filter(b => b.estadoPublicacion === 'Publicado' && !b.marketingGenerado);

// === METRICAS DE SOPORTE ===
const ticketsAbiertos = supportParsed.filter(t => t.estadoTicket === 'Nuevo' || t.estadoTicket === 'En revision');
const ticketsPorTema = {};
supportParsed.forEach(t => {
  ticketsPorTema[t.tema] = (ticketsPorTema[t.tema] || 0) + 1;
});
const ticketsUrgentes = supportParsed.filter(t => t.prioridad === 'Urgente' || t.prioridad === 'Alta');

// === ALERTAS ===
const alertas = [];
if (librosSinVender30.length > 0) alertas.push(`${librosSinVender30.length} libros sin vender en mas de 30 dias`);
if (librosSinVender90.length > 0) alertas.push(`${librosSinVender90.length} libros sin vender en mas de 90 dias - considerar rebaja`);
if (sinMarketing.length > 0) alertas.push(`${sinMarketing.length} libros publicados sin marketing generado`);
if (ticketsUrgentes.length > 0) alertas.push(`${ticketsUrgentes.length} tickets de soporte urgentes pendientes`);

// === CONSTRUIR REPORTE ===
const reporte = {
  fecha: formatDate(now),
  periodo: `Semana del ${formatDate(oneWeekAgo)} al ${formatDate(now)}`,

  // Ventas
  ventasSemana: totalVentasSemana.toFixed(2),
  ventasMes: totalVentasMes.toFixed(2),
  numPedidosSemana: numPedidosSemana,
  numLibrosVendidosSemana: numLibrosVendidosSemana,
  ticketMedio: ticketMedio.toFixed(2),
  ventasPorPlataforma: Object.entries(ventasPorPlataforma).map(([k, v]) => `${k}: ${v.toFixed(2)} eur`).join(', '),
  topGeneros: topGeneros.map(([g, n]) => `${g} (${n})`).join(', '),
  topAutores: topAutores.map(([a, n]) => `${a} (${n})`).join(', '),

  // Rentabilidad
  costeTotalVendido: costeTotalVendido.toFixed(2),
  margenBrutoEur: margenBrutoEur.toFixed(2),
  margenBrutoPct: margenBrutoPct.toFixed(1),
  margenPorGenero: Object.entries(margenPorGenero).map(([g, d]) => `${g}: ${d.margen.toFixed(2)} eur`).join(', '),

  // Inventario
  stockDisponible: stockDisponible.length,
  stockReservado: stockReservado.length,
  stockVendido: stockVendido.length,
  stockRetirado: stockRetirado.length,
  valorInventario: valorInventario.toFixed(2),
  costeInventario: costeInventario.toFixed(2),
  librosSinVender30: librosSinVender30.length,
  librosSinVender60: librosSinVender60.length,
  librosSinVender90: librosSinVender90.length,
  stockPorGenero: Object.entries(stockPorGenero).map(([g, n]) => `${g}: ${n}`).join(', '),
  sinMarketing: sinMarketing.length,

  // Soporte
  ticketsAbiertos: ticketsAbiertos.length,
  ticketsPorTema: Object.entries(ticketsPorTema).map(([t, n]) => `${t}: ${n}`).join(', '),
  ticketsUrgentes: ticketsUrgentes.length,

  // Alertas
  alertas: alertas,
  numAlertas: alertas.length
};

return [{ json: reporte }];

